package com.luminor.tavernquest.feature.settings
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.repository.SettingsRepository;import com.luminor.tavernquest.domain.repository.AuthRepository;import com.luminor.tavernquest.domain.usecase.settings.ResetGameUseCase;import com.luminor.tavernquest.data.local.database.TavernQuestDatabase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class SettingsViewModel @Inject constructor(private val repo:SettingsRepository,private val auth:AuthRepository,private val db:TavernQuestDatabase,private val reset:ResetGameUseCase):ViewModel(){val ui=repo.observe().map{SettingsUiState(it.soundEnabled,it.hapticsEnabled)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),SettingsUiState());fun sound(v:Boolean){viewModelScope.launch{repo.setSound(v)}};fun haptics(v:Boolean){viewModelScope.launch{repo.setHaptics(v)}};fun reset(onComplete:()->Unit){viewModelScope.launch{reset();onComplete()}};fun logout(onComplete:()->Unit){viewModelScope.launch{db.clearAllTables();auth.logout();onComplete()}}}
